const { createHash } = require('crypto');
const items = $input.all();

// 1. Verificação de concorrência / advisory lock
const firstItem = items[0]?.json;
if (firstItem && firstItem.acquired === false) {
  return [{
    json: {
      chat_id: 5281600644,
      text: '⚠️ <b>Reflexion Engine Semanal (WF-104)</b>\n\nExecução ignorada: outro processo de reflexão já está em andamento (lock 104104 ocupado).',
      lock_busy: true,
      has_candidates: false,
      has_auto: false
    }
  }];
}

// 2. Filtrar desfechos válidos da semana
const outcomes = items
  .map(i => i.json)
  .filter(j => j && j.id && j.tenant_id);

const tenant_id = outcomes[0]?.tenant_id || 'default';
const total = outcomes.length;
const minSample = 5;
const nowIso = new Date().toISOString().slice(0, 10);

if (total < minSample) {
  const card = `🧠 <b>Balanço Semanal de Aprendizado 360 (WF-104)</b>\n` +
    `📅 <i>Semana: ${nowIso}</i> | Tenant: <code>${tenant_id}</code>\n\n` +
    `• <b>Amostra insuficiente na semana:</b> ${total} registros observados (Mínimo: ${minSample}).\n` +
    `• Nenhuma diretriz foi inferida para preservar a integridade das políticas.\n` +
    `• O motor continuará acumulando desfechos.`;
  return [{ json: { chat_id: 5281600644, text: card, insufficient: true, total, has_candidates: false, has_auto: false } }];
}

let accepted = 0;
let edited = 0;
let rejected = 0;
const patterns = {};

for (const o of outcomes) {
  if (o.outcome_type === 'ACEITO_INTEGRAL') accepted++;
  else if (o.outcome_type === 'EDITADO_POR_RAFAEL') {
    edited++;
    const key = `${o.domain || 'GERAL'}:${o.delta_analysis?.edit_type || 'MODIFICADO'}`;
    patterns[key] = (patterns[key] || 0) + 1;
  }
  else if (o.outcome_type === 'RECUSADO_COM_MOTIVO') {
    rejected++;
    const key = `${o.domain || 'GERAL'}:REJEITADO`;
    patterns[key] = (patterns[key] || 0) + 1;
  }
}

const useful = accepted + edited;
const durPct = ((useful / total) * 100).toFixed(1);
const statusIcon = durPct >= 85.0 ? '🟢 <b>META BATIDA</b>' : '🟡 <b>ABAIXO DA META</b>';

function deterministicUuid(seed) {
  const hash = createHash('sha256').update(seed, 'utf8').digest('hex');
  return [
    hash.slice(0, 8),
    hash.slice(8, 12),
    '5' + hash.slice(13, 16),
    ((parseInt(hash.slice(16, 18), 16) & 0x3f) | 0x80).toString(16) + hash.slice(18, 20),
    hash.slice(20, 32)
  ].join('-');
}

// Filtros estritos de Autopromoção
const ALLOWED_AUTO_CATEGORIES = new Set([
  'STYLE_FORMATTING',
  'COMMUNICATION_CADENCE',
  'CONVERSATIONAL_PREFERENCE',
  'PRESENTATION_ORDER',
  'EXECUTIVE_SUMMARY_STYLE'
]);

const candidates = [];
const autoPromotedList = [];
const manualReviewList = [];

for (const [key, count] of Object.entries(patterns)) {
  if (count >= 2) {
    const [dom, type] = key.split(':');
    let rule = `Ajustar propostas em ${dom} conforme preferências de Rafael.`;
    let risk = 'LOW';
    let category = 'COMMUNICATION_CADENCE';
    let prefType = null;
    let prefVal = null;
    let canonicalText = null;

    if (type === 'MADE_MORE_CONCISE' || type === 'TEXT_LENGTH_REDUCED') {
      rule = 'Apresentar respostas e pareceres em formato compacto e direto ao ponto.';
      category = 'STYLE_FORMATTING';
      prefType = 'RESPONSE_LENGTH';
      prefVal = 'COMPACT';
      canonicalText = rule;
    } else if (type === 'TABLE_REQUESTED') {
      rule = 'Exibir dados quantitativos e tabelas antes de explicacoes textuais.';
      category = 'PRESENTATION_ORDER';
      prefType = 'TABLE_PREFERENCE';
      prefVal = 'TABLE_FIRST';
      canonicalText = rule;
    } else if (type === 'REJEITADO') {
      rule = `Em ${dom}, reavaliar ofertas e argumentos previamente recusados.`;
      risk = 'HIGH';
      category = 'COMPLIANCE';
    }

    const scope = 'INDICATOR'; // NUNCA GLOBAL para inferência autônoma
    const score = 0.85; // Score de cálculo determinístico
    const seed = `${tenant_id}:${dom}:${type}:${rule}`;
    const candidateId = deterministicUuid(seed);
    const learning_run_id = `run-${candidateId.slice(0, 8)}`;
    const idempotency_key = `pk:${tenant_id}:${dom}:${deterministicUuid(dom + ':' + type).slice(0, 16)}`;

    // Avaliação Estrita dos Filtros Soberanos N2.4 / N7A
    const isCategoryAllowed = ALLOWED_AUTO_CATEGORIES.has(category);
    const isScoreEligible = score >= 0.75;
    const isFreqEligible = count >= 2;
    const isRiskLow = risk === 'LOW';
    const isScopeSafe = scope !== 'GLOBAL';
    const hasCanonicalTemplate = Boolean(prefType && prefVal && canonicalText);

    const eligibleForAuto = isCategoryAllowed && isScoreEligible && isFreqEligible && isRiskLow && isScopeSafe && hasCanonicalTemplate;

    const candObj = {
      id: candidateId,
      tenant_id,
      category: eligibleForAuto ? 'STRUCTURED_PREFERENCE' : category,
      scope,
      target_ref: dom,
      learned_rule: canonicalText || rule,
      confidence_score: score,
      risk_level: risk,
      frequency: count,
      learning_run_id,
      idempotency_key,
      promotion_mode: eligibleForAuto ? 'AUTO' : 'MANUAL_REVIEW',
      promotion_score: score,
      preference_type: prefType,
      preference_value: prefVal,
      canonical_rule_text: canonicalText
    };

    candidates.push(candObj);
    if (eligibleForAuto) {
      autoPromotedList.push(candObj);
    } else {
      manualReviewList.push(candObj);
    }
  }
}

let card = `🧠 <b>Balanço Semanal de Aprendizado 360 (WF-104)</b>\n` +
  `📅 <i>Semana: ${nowIso}</i> | Tenant: <code>${tenant_id}</code>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +
  `📊 <b>Métricas de Assertividade da IA:</b>\n` +
  `• <b>Total de Propostas:</b> ${total}\n` +
  `• <b>Úteis / Aceitas:</b> ${useful} (${durPct}% de utilidade)\n` +
  `• <b>Ajustadas por Você:</b> ${edited}\n` +
  `• <b>Recusadas:</b> ${rejected}\n` +
  `• <b>Status da Meta (DUR ≥ 85%):</b> ${statusIcon}\n\n`;

if (autoPromotedList.length > 0) {
  card += `⚡ <b>Diretrizes Autopromovidas (Baixo Risco / Preferência Estruturada):</b>\n`;
  for (const a of autoPromotedList) {
    card += `  ✅ <b>${a.preference_type}:</b> <i>${a.learned_rule}</i> (Score: ${a.promotion_score})\n`;
  }
  card += `\n`;
}

if (manualReviewList.length > 0) {
  card += `🔍 <b>Diretrizes Submetidas para Revisão Soberana de Rafael:</b>\n`;
  for (const c of manualReviewList) {
    card += `  • <code>/aprovardiretriz ${c.id}</code>\n    <i>${c.learned_rule}</i>\n`;
  }
  card += `\n`;
}

if (candidates.length === 0) {
  card += `💡 Nenhuma divergência recorrente detectada nesta semana. Sistema estável e consistente.\n\n`;
}

card += `━━━━━━━━━━━━━━━━━━━━━━━━━━\n<i>Ciclo de reflexão consolidado via RPCs transacionais PostgreSQL.</i>`;

if (candidates.length === 0) {
  return [{
    json: {
      chat_id: 5281600644,
      text: card,
      has_candidates: false,
      has_auto: false,
      tenant_id,
      nowIso
    }
  }];
}

return candidates.map(c => ({
  json: {
    ...c,
    text: card,
    chat_id: 5281600644,
    has_candidates: true,
    has_auto: c.promotion_mode === 'AUTO',
    nowIso
  }
}));
